/**
 * Suanzi Counter Script
 * 复刻不蒜子计数器功能
 */

(function() {
    // 生成 UUID
    function generateUUID() {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            var r = Math.random() * 16 | 0,
                v = c == 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    }

    // 获取或设置 UUID Cookie
    function getOrCreateUUID() {
        var uuid = getCookie('suanzi_uuid');
        if (!uuid) {
            uuid = generateUUID();
            setCookie('suanzi_uuid', uuid, 365); // 有效期 1 年
        }
        return uuid;
    }

    // 获取 Cookie
    function getCookie(name) {
        var nameEQ = name + "=";
        var ca = document.cookie.split(';');
        for(var i = 0; i < ca.length; i++) {
            var c = ca[i];
            while (c.charAt(0) == ' ') c = c.substring(1, c.length);
            if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
        }
        return null;
    }

    // 设置 Cookie
    function setCookie(name, value, days) {
        var expires = "";
        if (days) {
            var date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = "; expires=" + date.toUTCString();
        }
        document.cookie = name + "=" + (value || "") + expires + "; path=/";
    }

    // 获取当前域名和路径
    function getDomainAndPath() {
        var domain = window.location.hostname;
        var path = window.location.pathname;
        return { domain: domain, path: path };
    }

    // 发送计数请求
    function sendCountRequest(type, path, callback) {
        var uuid = getOrCreateUUID();
        var { domain } = getDomainAndPath();
        
        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/api/count', true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        
        xhr.onreadystatechange = function() {
            if (xhr.readyState === 4) {
                if (xhr.status === 200) {
                    if (callback) callback(null, JSON.parse(xhr.responseText));
                } else {
                    if (callback) callback(new Error('Request failed: ' + xhr.status));
                }
            }
        };
        
        var data = {
            domain: domain,
            type: type,
            path: path || '',
            uuid: uuid
        };
        
        xhr.send(JSON.stringify(data));
    }

    // 查询计数值
    function queryCount(type, path, callback) {
        var { domain } = getDomainAndPath();
        var url = '/api/count?domain=' + encodeURIComponent(domain) + 
                  '&type=' + encodeURIComponent(type);
        if (path) {
            url += '&path=' + encodeURIComponent(path);
        }
        
        var xhr = new XMLHttpRequest();
        xhr.open('GET', url, true);
        
        xhr.onreadystatechange = function() {
            if (xhr.readyState === 4) {
                if (xhr.status === 200) {
                    if (callback) callback(null, JSON.parse(xhr.responseText));
                } else {
                    if (callback) callback(new Error('Request failed: ' + xhr.status));
                }
            }
        };
        
        xhr.send();
    }

    // 回填计数值到页面
    function fillCountValue(elementId, count) {
        var element = document.getElementById(elementId);
        if (element) {
            element.textContent = count;
        }
    }

    // 初始化计数
    function initCounters() {
        var domainInfo = getDomainAndPath();
        
        // 站点 PV 计数
        sendCountRequest('site_pv', '', function(err, result) {
            if (!err) {
                queryCount('site_pv', '', function(err, data) {
                    if (!err && data && data.count !== undefined) {
                        fillCountValue('busuanzi_value_site_pv', data.count);
                    }
                });
            }
        });
        
        // 站点 UV 计数
        sendCountRequest('site_uv', '', function(err, result) {
            if (!err) {
                queryCount('site_uv', '', function(err, data) {
                    if (!err && data && data.count !== undefined) {
                        fillCountValue('busuanzi_value_site_uv', data.count);
                    }
                });
            }
        });
        
        // 页面 PV 计数
        sendCountRequest('page_pv', domainInfo.path, function(err, result) {
            if (!err) {
                queryCount('page_pv', domainInfo.path, function(err, data) {
                    if (!err && data && data.count !== undefined) {
                        fillCountValue('busuanzi_value_page_pv', data.count);
                    }
                });
            }
        });
    }

    // 页面加载完成后初始化
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCounters);
    } else {
        initCounters();
    }
})();